<?php
declare(strict_types=1);
namespace Annam;
final class LocalRecovery {
    public static function create(Database $db,string $destination):array {
        if(file_exists($destination)||is_link($destination))throw new \RuntimeException('Choose a new backup file.');$store=new Store($db);$inventory=(new Backup($store))->references();if(!is_dir(Media::root()))throw new \RuntimeException('The media folder is missing.');if(getenv('APP_ENV')==='production'&&($inventory['missing']||$inventory['external']))throw new \RuntimeException('Restore missing media before creating a complete production backup.');
        $work=ANNAM_ROOT.'/storage/local-recovery-'.bin2hex(random_bytes(8));mkdir($work,0700);$zip=null;
        try{$db->snapshot($work.'/database.sqlite');$zip=new \ZipArchive();if($zip->open($work.'/archive.zip',\ZipArchive::CREATE|\ZipArchive::OVERWRITE)!==true)throw new \RuntimeException('Cannot create backup archive.');$snapshot=new \PDO('sqlite:'.$work.'/database.sqlite',null,null,[\PDO::ATTR_ERRMODE=>\PDO::ERRMODE_EXCEPTION]);if($snapshot->query('PRAGMA integrity_check')->fetchColumn()!=='ok'||$snapshot->query('PRAGMA foreign_key_check')->fetch())throw new \RuntimeException('Database snapshot integrity failed.');$counts=[];foreach(array_keys(json_decode(file_get_contents(ANNAM_ROOT.'/resources/sqlite-types.json'),true)) as $table)$counts[$table]=(int)$snapshot->query('SELECT COUNT(*) FROM "'.$table.'"')->fetchColumn();$snapshot=null;$manifest=['format'=>2,'database'=>'SQLite snapshot including committed WAL data','created_at'=>date('c'),'tables'=>$counts,'files'=>[],'media_inventory'=>['missing'=>$inventory['missing'],'external'=>$inventory['external']]];
            $add=function($file,$name)use(&$manifest,$zip){$zip->addFile($file,$name);$manifest['files'][$name]=hash_file('sha256',$file);};$add($work.'/database.sqlite','database.sqlite');$add(ANNAM_ROOT.'/resources/sqlite-schema.sql','schema.sql');
            foreach(['media'=>Media::root(),'bills'=>ANNAM_ROOT.'/storage/bills'] as $prefix=>$root)if(is_dir($root))foreach(new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator($root,\FilesystemIterator::SKIP_DOTS)) as $file)if($file->isFile()&&!$file->isLink())$add($file->getPathname(),$prefix.'/'.substr($file->getPathname(),strlen(rtrim($root,'/'))+1));
            $keys=[];foreach(['APP_SECRET','SECRETS_KEY','APP_URL','STORE_SLUG','MEDIA_ROOT','PAYMENTS_ENABLED','MESSAGING_ENABLED','REQUIRE_CRON'] as $key)$keys[$key]=getenv($key)?:'';file_put_contents($work.'/keys.json',json_encode($keys,JSON_THROW_ON_ERROR));$add($work.'/keys.json','recovery/keys.json');if(is_file(Installation::file()))$add(Installation::file(),'recovery/installation.json');$zip->addFromString('MANIFEST.json',json_encode($manifest,JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR));$zip->close();$zip=null;Recovery::seal($work.'/archive.zip',$destination);return ['encrypted'=>true,'driver'=>'sqlite','tables'=>count($counts),'rows'=>array_sum($counts),'files'=>count($manifest['files']),'missing_media'=>count($inventory['missing'])];
        }finally{if($zip)$zip->close();foreach(new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator($work,\FilesystemIterator::SKIP_DOTS),\RecursiveIteratorIterator::CHILD_FIRST) as $file)$file->isDir()?rmdir($file->getPathname()):unlink($file->getPathname());rmdir($work);}
    }
    public static function restore(string $source,string $destination):void {
        if(!str_starts_with($destination,'/')||str_contains($destination,'/public_html/')||str_starts_with($destination,ANNAM_ROOT.'/public/')||file_exists($destination)||is_link($destination))throw new \RuntimeException('Restore only to a new private database file.');
        if(!is_file($source)||filesize($source)===0)throw new \RuntimeException('The SQLite snapshot file is missing.');
        $test=new \PDO('sqlite:'.$source,null,null,[\PDO::ATTR_ERRMODE=>\PDO::ERRMODE_EXCEPTION]);if((int)$test->query("SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name IN ('orders_order','tenancy_tenant')")->fetchColumn()!==2||$test->query('PRAGMA integrity_check')->fetchColumn()!=='ok'||$test->query('PRAGMA foreign_key_check')->fetch())throw new \RuntimeException('Database snapshot integrity failed.');$test=null;$tmp=$destination.'.'.bin2hex(random_bytes(8));if(!copy($source,$tmp))throw new \RuntimeException('Cannot restore database.');chmod($tmp,0600);if(!rename($tmp,$destination)){unlink($tmp);throw new \RuntimeException('Cannot activate restored database.');}
    }
}
